//! Contains search entity models

use serde::Serialize;
use thiserror::Error;

use crate::domain::models::{funder::Funder as FunderDetails, parliament_member::ParliamentMember};

/// Default primary search threshold.
pub const DEFAULT_SEARCH_STRICTNESS: f32 = 0.8;

const MAX_STRICTNESS: f32 = 1_f32;
const MIN_STRICTNESS: f32 = 0_f32;
const MIN_ENTRIES: u8 = 1;

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
/// Name that supplied a search result's winning score.
pub enum SearchMatchSource {
    /// The canonical name won, including equal scores.
    Name,
    /// An observed alias scored higher than the canonical name.
    Alias {
        /// Original observed spelling.
        name: String,
    },
}

#[derive(Clone, Debug, PartialEq, Eq)]
/// Canonical funder identity and its search match provenance.
pub struct FunderSearchMatch {
    funder: FunderDetails,
    source: SearchMatchSource,
}

impl FunderSearchMatch {
    #[must_use]
    /// Creates a search result for a canonical identity.
    pub const fn new(funder: FunderDetails, source: SearchMatchSource) -> Self {
        Self { funder, source }
    }

    #[must_use]
    /// Canonical funder.
    pub const fn funder(&self) -> &FunderDetails {
        &self.funder
    }

    #[must_use]
    /// Winning match source.
    pub const fn source(&self) -> &SearchMatchSource {
        &self.source
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
/// Search entity kind
pub enum Entity {
    /// Company entity
    Funder(FunderSearchMatch),
    /// Member entitiy
    ParliamentMember(ParliamentMember),
}

impl Entity {
    #[must_use]
    /// Entity name
    pub fn name(&self) -> &str {
        match self {
            Self::Funder(kind) => kind.funder().name(),
            Self::ParliamentMember(mp) => mp.name(),
        }
    }

    #[must_use]
    /// Entity kind
    pub const fn kind(&self) -> &str {
        match self {
            Self::Funder(_) => "Funder",
            Self::ParliamentMember(_) => "MP",
        }
    }

    #[must_use]
    /// Funder kind
    pub fn funder_kind(&self) -> Option<&str> {
        match self {
            Self::Funder(kind) => Some(kind.funder().kind()),
            Self::ParliamentMember(_) => None,
        }
    }
}

impl From<&ParliamentMember> for Entity {
    fn from(value: &ParliamentMember) -> Self {
        Self::ParliamentMember(value.clone())
    }
}

impl From<&FunderSearchMatch> for Entity {
    fn from(value: &FunderSearchMatch) -> Self {
        Self::Funder(value.clone())
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
/// Search entity name
pub struct EntityName(String);

#[derive(Clone, Debug, PartialEq)]
/// Data required to search entities
pub struct EntitySearchRequest {
    term: String,
    strictness: f32,
    max_entries: u8,
}

impl EntitySearchRequest {
    #[must_use]
    /// Search term
    pub const fn term(&self) -> &str {
        self.term.as_str()
    }

    #[must_use]
    /// Search strictness
    pub const fn strictness(&self) -> f32 {
        self.strictness
    }

    #[must_use]
    /// Max result set
    pub const fn max_entries(&self) -> u8 {
        self.max_entries
    }
}

impl EntitySearchRequest {
    /// Creates new instance with [`MAX_STRICTNESS`]
    ///
    /// # Errors
    /// - See [`Self::new_with_strictness`]
    pub fn new_strict(term: String, max_entries: u8) -> Result<Self, EntitySearchError> {
        Self::new_with_strictness(term, max_entries, MAX_STRICTNESS)
    }
    /// Creates new instance with variable strictness
    ///
    /// # Errors
    /// - Term too short
    /// - Too few entries
    /// - Invalid strictness
    pub fn new_with_strictness(
        term: String,
        max_entries: u8,
        strictness: f32,
    ) -> Result<Self, EntitySearchError> {
        // It will be a u8
        #[allow(clippy::cast_possible_truncation)]
        if term.trim().len() < 3 {
            return Err(EntitySearchError::InvalidTerm(term.trim().len() as u8));
        }
        if max_entries < MIN_ENTRIES {
            return Err(EntitySearchError::TooFewEntries);
        }
        if !strictness.is_finite() || strictness < MIN_STRICTNESS || strictness > MAX_STRICTNESS {
            return Err(EntitySearchError::InvalidStrictness(strictness));
        }
        Ok(Self {
            term,
            strictness,
            max_entries,
        })
    }
}

/// Errors related to entity search
#[derive(Error, Debug)]
pub enum EntitySearchError {
    /// Unexpected runtime errors, usually from the database
    #[error("unexpected error occurred: {0}")]
    UnexpectedError(String),

    /// Term too short for generating valid search results
    #[error("term must be at last three characters long; received {0}")]
    InvalidTerm(u8),

    /// Invalid strictness value
    #[error("at least one entry must be expected to return")]
    TooFewEntries,

    /// Invalid strictness value
    #[error("strictness must be between {MIN_STRICTNESS} and {MAX_STRICTNESS}; get {0}")]
    InvalidStrictness(f32),
}

#[cfg(test)]
mod strictness {
    use super::EntitySearchRequest;

    #[test]
    fn rejects_non_finite_thresholds() {
        for threshold in [f32::NAN, f32::INFINITY, f32::NEG_INFINITY] {
            assert!(
                EntitySearchRequest::new_with_strictness("West".into(), 10, threshold).is_err()
            );
        }
    }
}

/// Primary funder matches and eligibility before the result limit.
#[derive(Clone)]
pub struct FunderSearchResults {
    /// Ranked, limited canonical identities.
    pub matches: Vec<(
        FunderSearchMatch,
        crate::domain::models::search_similarity::SearchSimilarity,
    )>,
    /// Whether any qualifying individual exists, including outside the limit.
    pub has_qualifying_individual: bool,
}

/// Ranking for a phonetic match, independent of primary similarity.
#[derive(Clone)]
pub struct PhoneticRank {
    distance: u32,
    similarity: crate::domain::models::search_similarity::SearchSimilarity,
}

impl PhoneticRank {
    /// Creates a rank from a nonnegative token edit distance.
    #[must_use]
    pub const fn new(
        distance: u32,
        similarity: crate::domain::models::search_similarity::SearchSimilarity,
    ) -> Self {
        Self {
            distance,
            similarity,
        }
    }

use crate::{
    domain::{
        models::{
            entity_details::{
                CategoryTotal, CurrencyBreakdown, DeclaredFunding, FunderDeclaration,
                FunderDetails, FunderProfile, FunderReference, MemberCurrencyTotal,
                MemberDeclaration, MemberDetails, MemberProfile, MemberSummary, PartyTotal,
                RecipientAllocation,
            },
            funder::FunderId,
            parliament_member::{MemberId, MemberIdError},
        },
        services::{
            entity_details::{EntityDetailsError, EntityDetailsService},
            entity_search::EntitySearchService,
        },
    },
    inbound::http::{error::ApiError, state::AppState, success::ApiSuccess},
};
use axum::{
    extract::{Path, State},
    http::StatusCode,
};
use chrono::{DateTime, Utc};
use serde::Serialize;

impl From<EntityDetailsError> for ApiError {
    fn from(error: EntityDetailsError) -> Self {
        tracing::error!(?error, "entity details failed");
        match error {
            EntityDetailsError::NotFound => Self::NotFound,
            EntityDetailsError::Unexpected(_) => Self::InternalServerError,
        }
    }
}

impl From<MemberIdError> for ApiError {
    fn from(error: MemberIdError) -> Self {
        tracing::error!(?error, "invalid member ID");
        Self::UnprocessibleEntity(error.to_string())
    }
}

impl From<uuid::Error> for ApiError {
    fn from(error: uuid::Error) -> Self {
        tracing::error!(?error, "invalid funder ID");
        Self::UnprocessibleEntity("Invalid funder ID".into())
    }
}

#[derive(Serialize)]
pub struct MemberResponse {
    id: String,
    name: String,
    party_id: i32,
    party_name: String,
    membership_from: String,
    is_current_commons: bool,
}
impl From<MemberProfile> for MemberResponse {
    fn from(member: MemberProfile) -> Self {
        Self {
            id: member.id.value().to_string(),
            name: member.name,
            party_id: member.party_id,
            party_name: member.party_name,
            membership_from: member.membership_from,
            is_current_commons: member.is_current_commons,
        }
    }
}

#[derive(Serialize)]
pub struct FunderReferenceResponse {
    id: String,
    name: String,
}
impl From<FunderReference> for FunderReferenceResponse {
    fn from(funder: FunderReference) -> Self {
        Self {
            id: funder.id.value().to_string(),
            name: funder.name,
        }
    }
}

#[derive(Serialize)]
pub struct FundingResponse {
    funder: Option<FunderReferenceResponse>,
    amount: Option<String>,
    currency: Option<String>,
    payment_type: Option<String>,
}
impl From<DeclaredFunding> for FundingResponse {
    fn from(entry: DeclaredFunding) -> Self {
        Self {
            funder: entry.funder.map(Into::into),
            amount: entry
                .amount
                .map(|amount| amount.normalized().to_plain_string()),
            currency: entry.currency,
            payment_type: entry.payment_type,
        }
    }
}

#[derive(Serialize)]
pub struct DeclarationResponse {
    source_id: i32,
    category_id: i32,
    category_name: String,
    registered_at: Option<DateTime<Utc>>,
    entries: Vec<FundingResponse>,
}
impl From<MemberDeclaration> for DeclarationResponse {
    fn from(declaration: MemberDeclaration) -> Self {
        Self {
            source_id: declaration.source_id,
            category_id: declaration.category.source_id(),
            category_name: declaration.category_name,
            registered_at: declaration.registered_at,
            entries: declaration.entries.into_iter().map(Into::into).collect(),
        }
    }
}

#[derive(Serialize)]
pub struct MemberDetailsResponse {
    member: MemberResponse,
    declarations: Vec<DeclarationResponse>,
mod entity_details;
pub use entity_details::{funder_details, member_details};

use axum::{
    extract::{Query, State},
    http::StatusCode,
};
use serde::{Deserialize, Serialize};

use crate::{
    domain::{
        models::entity_search::{
            Entity, EntitySearchError, EntitySearchRequest, SearchMatchSource,
        },
        services::{entity_details::EntityDetailsService, entity_search::EntitySearchService},
    },
    inbound::http::{error::ApiError, state::AppState, success::ApiSuccess},
};

#[derive(Debug, Clone, PartialEq, Deserialize)]
pub struct SearchEntitiesHttpRequest {
    term: String,
    max_entries: u8,
    strictness: Option<f32>,
}

impl SearchEntitiesHttpRequest {
    /// Converts the HTTP request body into a domain request.
    fn try_into_domain(self) -> Result<EntitySearchRequest, EntitySearchError> {
        match self.strictness {
            Some(s) => EntitySearchRequest::new_with_strictness(self.term, self.max_entries, s),
            None => EntitySearchRequest::new_with_strictness(
                self.term,
                self.max_entries,
                crate::domain::models::entity_search::DEFAULT_SEARCH_STRICTNESS,
            ),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct SearchEntityResponseData {
    entities: Vec<SearchEntity>,
}

impl From<&[Entity]> for SearchEntityResponseData {
    fn from(value: &[Entity]) -> Self {
        let entities = value.iter().map(SearchEntity::from).collect();
        Self { entities }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct SearchEntity {
    id: String,
    name: String,
    kind: String,
    funder_kind: Option<String>,
    match_source: SearchMatchSource,
}

impl From<&Entity> for SearchEntity {
    fn from(value: &Entity) -> Self {
        Self {
            id: match value {
                Entity::Funder(funder) => funder.funder().id().value().to_string(),
                Entity::ParliamentMember(member) => member.member_id().to_string(),
            },
            match_source: match value {
                Entity::Funder(funder) => funder.source().clone(),
                Entity::ParliamentMember(_) => SearchMatchSource::Name,
            },
            name: value.name().to_string(),
            kind: value.kind().to_string(),
            funder_kind: value.funder_kind().map(String::from),
        }
    }
}

impl From<EntitySearchError> for ApiError {
    fn from(value: EntitySearchError) -> Self {
        tracing::error!(error = ?value, "entity search failed");
        match value {
            EntitySearchError::InvalidTerm(_)
            | EntitySearchError::InvalidStrictness(_)
            | EntitySearchError::TooFewEntries => Self::UnprocessibleEntity(value.to_string()),
            EntitySearchError::UnexpectedError(_) => Self::InternalServerError,
        }
    }
}

pub async fn search_entities<E: EntitySearchService, D: EntityDetailsService>(
    State(state): State<AppState<E, D>>,
    Query(query): Query<SearchEntitiesHttpRequest>,
) -> Result<ApiSuccess<SearchEntityResponseData>, ApiError> {
    let domain_req = query.try_into_domain()?;
    state
        .entity_search_service
        .search_entities(&domain_req)
        .await
        .map_err(ApiError::from)
        .map(|ref entities| ApiSuccess::new(StatusCode::OK, entities.as_slice().into()))
}

